from sage.all import *

def get_encrypted_flag(r, offset, chunk_size):
    try:
        r.recvuntil(b'offset,len:')
        r.sendline(f'{offset},{chunk_size}'.encode())

        enc_line = r.recvline().strip().decode()
        enc_flag = int(enc_line.split(': ')[1], 16)

        rounds_line = r.recvline().strip().decode()
        rounds = int(rounds_line.split(' ')[2])

        return enc_flag, rounds
    except:
        return None, None

