        iterations += 1
        ct = (ct * multiplier) % n

        bit = oracle_query(r, ct)
        if bit is None:
            return None

        if bit % 2 == 0:
            upper_bound = (upper_bound + lower_bound) // 2
        else:
            lower_bound = (upper_bound + lower_bound) // 2

    return lower_bound

