N = 0xc8dd5cd87ca3f5b9dbdeaf3841fb2a6c000b3fac463536d2a09a7f9041a00692c3deab14bc5be43dea67dcbcfaef3d77ebd2a36bd0e2c9de6d5e1cbd2fd1e4cec37ee47a0f9b1dc7b23e90927ed51c8b5cec947b8af6c875b53cd6f31e1b6fac0c3e1cfee48c9c584d3a94488a14f62506ea89c0e4c32eb7c46cfe0bc9ba17
E = 65537

class OracleAttack:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.n = N
        self.e = E

    def get_connection(self):
        return remote(self.host, self.port, level='error')

    def get_encrypted_flag(self, r, offset, chunk_size):
        try:
            r.recvuntil(b'offset,len:')
            r.sendline(f'{offset},{chunk_size}'.encode())
            time.sleep(0.1)

            enc_line = r.recvline().strip().decode()
            enc_flag = int(enc_line.split(': ')[1], 16)

            rounds_line = r.recvline().strip().decode()
            rounds = int(rounds_line.split(' ')[2])

            return enc_flag, rounds
        except Exception as e:
            print(f"Error in get_encrypted_flag: {e}")
            return None, None

    def oracle_query(self, r, ct_hex):
        try:
            r.recvuntil(b'2. decrypt\n')
            r.sendline(b'2')
            time.sleep(0.1)
            r.recvuntil(b'input:')
            r.sendline(hex(ct_hex)[2:].encode())
            time.sleep(0.1)
            resp = r.recvline().strip().decode()
            return int(resp, 16)
        except Exception as e:
            print(f"Error in oracle_query: {e}")
            return None

    def lsb_oracle_attack(self, r, ct):
        lower_bound = 0
        upper_bound = self.n

        multiplier = pow(2, self.e, self.n)
        iterations = 0
        max_iterations = 1000

        print(f"Starting LSB oracle attack...")

        while upper_bound - lower_bound > 1 and iterations < max_iterations:
            iterations += 1
            ct = (ct * multiplier) % self.n

            bit = self.oracle_query(r, ct)
            if bit is None:
                print(f"Oracle query failed at iteration {iterations}")
                return None

            if bit % 2 == 0:
                upper_bound = (upper_bound + lower_bound) // 2
            else:
                lower_bound = (upper_bound + lower_bound) // 2

            if iterations % 10 == 0:
                print(f"Iteration {iterations}, bounds gap: {upper_bound - lower_bound}")

        return lower_bound

