class ConnectionPool:
    def __init__(self, size=5):
        self.size = size
        self.queue = Queue()
        self.lock = threading.Lock()

        for _ in range(size):
            try:
                conn = remote(HOST, PORT, timeout=2)
                self.queue.put(conn)
            except:
