        try:
            return self.queue.get(timeout=1)
        except:
            try:
                conn = remote(HOST, PORT, timeout=2)
                return conn
            except:
                return None

    def return_connection(self, conn):
        if conn:
            try:
                self.queue.put(conn)
            except:
                try:
                    conn.close()
                except:
                    pass

pool = ConnectionPool(5)

