    try:
        conn.recvuntil(b'====================================', timeout=1)
        conn.sendline(b'2')
        conn.recvuntil(b'input:', timeout=1)
        conn.sendline(hex(ct)[2:].encode())
        result = int(conn.recvline(timeout=1).strip().decode(), 16) & 1
        pool.return_connection(conn)
        return result
    except:
        try:
            conn.close()
        except:
            pass
        return None

