    conn = pool.get_connection()
    if not conn:
        return None

    try:
        conn.recvuntil(b'offset,len:', timeout=1)
        conn.sendline(b'0,16')  # Get larger chunk to avoid multiple requests
        resp = conn.recvline(timeout=1).decode().strip()
        conn.close()
        if resp.startswith('encrypted flag:'):
            return int(resp.split(':')[1].strip(), 16)
    except:
        try:
