from pwn import *
from gmpy2 import mpz, powmod
import time

HOST = 'crypto.chal.csaw.io'
PORT = 32333

# We don't need these since we can extract them from server responses
N = None
e = None

class Oracle:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.conn = None

    def connect(self):
        self.conn = remote(self.host, self.port, timeout=5)

    def disconnect(self):
        if self.conn:
            self.conn.close()
            self.conn = None

    def get_byte(self, ct):
        try:
            self.conn.recvuntil(b'====================================')
            self.conn.sendline(b'2')
            self.conn.recvuntil(b'input:')
            self.conn.sendline(hex(ct)[2:].encode())
            result = int(self.conn.recvline().strip().decode(), 16)
            return result & 0xff
        except:
            return None

    def get_flag_chunk(self, offset, length=2):
        try:
            self.conn.recvuntil(b'offset,len:')
            self.conn.sendline(f"{offset},{length}".encode())
            resp = self.conn.recvline().decode().strip()
            if resp.startswith('encrypted flag:'):
                return int(resp.split(':')[1].strip(), 16)
        except:
            return None

def lsb_oracle_attack(ct, oracle, N, e):
    ct = mpz(ct)
    lower = mpz(0)
    upper = N
    multiplier = powmod(2, e, N)
    current_ct = ct

    for _ in range(32):  # Enough bits to cover multiple bytes
        bit = oracle.get_byte(int(current_ct)) & 1
        if bit is None:
            return None

        mid = (lower + upper) >> 1
        if bit == 0:
            upper = mid
        else:
            lower = mid

        current_ct = (current_ct * multiplier) % N

    return int((lower + upper) >> 1)

def main():
    recovered = bytearray()
    offset = 0

    while len(recovered) < 64:  # Maximum expected flag length
        oracle = Oracle(HOST, PORT)
        oracle.connect()

        try:
            ct = oracle.get_flag_chunk(offset, 2)
            if ct is None:
                continue

            print(f"[+] Got encrypted chunk at offset {offset}: {hex(ct)}")

            # First request, get N and number of rounds
            if offset == 0:
                oracle.conn.recvuntil(b'rounds to go\n')
                rounds = int(oracle.conn.recvline().decode().split()[2])
                print(f"[+] Server allows {rounds} rounds")

            plaintext = lsb_oracle_attack(ct, oracle, N, e)

            if plaintext is not None:
                new_bytes = plaintext.to_bytes(2, 'big')
                recovered.extend(new_bytes)
                print(f"[+] Recovered so far: {recovered}")

                try:
                    text = recovered.decode('ascii', errors='ignore')
                    if 'flag{' in text and '}' in text:
                        start = text.index('flag{')
                        end = text.index('}', start) + 1
                        flag = text[start:end]
                        print(f"\n[!] Found flag: {flag}")
                        oracle.disconnect()
                        return flag
                except:
                    pass

            offset += 2

        except Exception as e:
            print(f"[-] Error: {e}")
        finally:
            oracle.disconnect()
            time.sleep(0.5)

if __name__ == '__main__':
    flag = main()
    if flag:
        print("Task completed successfully")
        with open('/tmp/flag.txt', 'w') as f:
            f.write(flag)

