from pwn import *
from gmpy2 import mpz, powmod
import time

HOST = 'crypto.chal.csaw.io'
PORT = 32333

def get_oracle_response(conn, ct):
    try:
        conn.recvuntil(b'====================================')
        conn.sendline(b'2')
        conn.recvuntil(b'input:')
        conn.sendline(hex(ct)[2:].encode())
        result = int(conn.recvline().strip().decode(), 16)
        return result & 0xff
    except:
        return None

def get_enc_flag(conn, offset=0, length=2):
    try:
        conn.recvuntil(b'offset,len:')
        conn.sendline(f"{offset},{length}".encode())
        resp = conn.recvline().decode().strip()
        if resp.startswith('encrypted flag:'):
            ct = int(resp.split(':')[1].strip(), 16)
            conn.recvuntil(b'rounds to go\n')
            return ct
    except:
        return None

def lsb_oracle_attack(ct, conn, N):
    ct = mpz(ct)
    lower = mpz(0)
    upper = N
    multiplier = powmod(2, 1, N)
    current_ct = ct

    while upper - lower > 1:
        lsb = get_oracle_response(conn, int(current_ct))
        if lsb is None:
            return None

        if lsb & 1 == 0:
            upper = (lower + upper) >> 1
        else:
            lower = (lower + upper) >> 1

        current_ct = (current_ct * multiplier) % N

    return int((lower + upper) >> 1)

def try_decrypt_chunk(offset, length=2):
    while True:
        try:
            conn = remote(HOST, PORT, timeout=5)
            ct = get_enc_flag(conn, offset, length)
            if ct is None:
                conn.close()
                continue

            # Get N by sending ct twice
            test_ct = ct
            lsb1 = get_oracle_response(conn, test_ct)
            lsb2 = get_oracle_response(conn, test_ct)
            if lsb1 != lsb2:
                conn.close()
                continue

            # First time we need to brute force N
            if offset == 0:
                for bits in range(1020, 1025):
                    N = 1 << bits
                    while N & 1 == 0:
                        N += 1
                    plaintext = lsb_oracle_attack(ct, conn, N)
                    if plaintext is not None:
                        try:
                            pt_bytes = long_to_bytes(plaintext)
                            if b'flag{' in pt_bytes:
                                print(f"[+] Found flag chunk: {pt_bytes}")
                                conn.close()
                                return pt_bytes
                        except:
                            pass
            else:
                # Use known N size for subsequent chunks
                N = 1 << 1024
                plaintext = lsb_oracle_attack(ct, conn, N)
                if plaintext is not None:
                    try:
                        pt_bytes = long_to_bytes(plaintext)
                        print(f"[+] Found chunk at offset {offset}: {pt_bytes}")
                        conn.close()
                        return pt_bytes
                    except:
                        pass

            conn.close()
        except Exception as e:
            try:
                conn.close()
            except:
                pass
            time.sleep(1)
            continue

