    # We'll decrypt in chunks of 2 bytes to maximize oracle queries
    recovered = bytearray()
    offset = 0

    while True:
        chunk = try_decrypt_chunk(offset)
        if chunk is None:
            break

        recovered.extend(chunk)
        print(f"[+] Recovered so far: {recovered}")

        try:
            text = recovered.decode('ascii', errors='ignore')
            if 'flag{' in text and '}' in text:
                start = text.index('flag{')
                end = text.index('}', start) + 1
                flag = text[start:end]
                print(f"\n[!] Found flag: {flag}")
                return flag
        except:
            pass

        offset += 2
        time.sleep(0.5)

    return None

